package net.minecraft.core;
import java.util.*;
public record BlockPos(int x,int y,int z) {
 public static final BlockPos ZERO=new BlockPos(0,0,0);
 public int getX(){return x;}public int getY(){return y;}public int getZ(){return z;}
 public BlockPos offset(int a,int b,int c){return new BlockPos(x+a,y+b,z+c);}
 public BlockPos immutable(){return this;}
 public double distSqr(BlockPos p){long a=x-p.x,b=y-p.y,c=z-p.z;return a*a+b*b+c*c;}
 public static Iterable<BlockPos> betweenClosed(BlockPos a,BlockPos b){List<BlockPos> r=new ArrayList<>();for(int x=a.x;x<=b.x;x++)for(int y=a.y;y<=b.y;y++)for(int z=a.z;z<=b.z;z++)r.add(new BlockPos(x,y,z));return r;}
}

