package ua.aia2.guard;
import java.util.*;import net.minecraft.server.level.*;import net.minecraft.world.level.block.entity.*;
public final class Aia2MachineGuard{public static final GuardPolicy POLICY=new GuardPolicy();public static boolean ready=true;public static boolean isReady(){return ready&&POLICY.isReady();}
 public static String synchronizedPlayerTeam(ServerPlayer p){return p==null||p.fake||!isReady()||!Objects.equals(p.syncedTeam,p.liveTeam)?"":p.liveTeam;}
 public static String getOwner(BlockEntity b){return b.owner;}
 public static void setOwner(BlockEntity b,String team){if(!(b.getLevel() instanceof ServerLevel)||team==null||team.isBlank())throw new IllegalArgumentException();if(!b.owner.isBlank()&&!team.equals(b.owner))throw new IllegalStateException();b.owner=team;b.ownerWrites++;b.setChanged();}
 public static int getRequiredStage(String id){return POLICY.getRequiredStage(id);}public static boolean mayObserveStage(String team,int stage){return isReady()&&POLICY.mayUseStage(stage,team);}
 public static boolean mayTick(BlockEntity b){return isReady()&&POLICY.mayTick(b.getBlockState().getBlock().id,b.owner);}
}

